  return byte.toString(16).padStart(2, '0');
}

export function formatPythonBytes(bytesLike) {
  const bytes = Uint8Array.from(bytesLike);
  const containsSingleQuote = bytes.includes(0x27);
  const containsDoubleQuote = bytes.includes(0x22);
  const quote = containsSingleQuote && !containsDoubleQuote ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);
  let output = `b${quote}`;

  for (const byte of bytes) {
    if (byte === 0x09) {
      output += '\\t';
      continue;
    }

    if (byte === 0x0a) {
      output += '\\n';
      continue;
    }

    if (byte === 0x0d) {
      output += '\\r';
      continue;
    }

    if (byte === 0x5c) {
      output += '\\\\';
      continue;
    }

    if (byte === quoteCode) {
      output += `\\${quote}`;
      continue;
    }

    if (byte >= 0x20 && byte <= 0x7e) {
      output += String.fromCharCode(byte);
      continue;
    }

    output += `\\x${toHex(byte)}`;
  }

  return `${output}${quote}`;
}

