export function main(argv = process.argv.slice(2)) {
  const programName = getProgramName(process.argv[1]);
  const parsed = parseArgs(argv);

  if (parsed.help) {
    writeHelp(programName);
    return;
  }

  const { key, iv, data1, data2 } = parsed.values;
  const aes = new AesModeOfOperationCBC(toUtf8Bytes(key), toUtf8Bytes(iv));
  const ciphertext1 = aes.encrypt(toUtf8Bytes(data1));
  const ciphertext2 = aes.encrypt(toUtf8Bytes(data2));

  process.stdout.write(`${formatPythonBytes(ciphertext1)}
`);
  process.stdout.write(`${formatPythonBytes(ciphertext2)}
`);
}

try {
