export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

export class CliArgumentError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CliArgumentError';
  }
}

import { CliArgumentError } from './errors.mjs';

const OPTION_SPECS = [
  { key: 'help', long: 'help', required: false, takesValue: false, metavar: null },
  { key: 'key', long: 'key', required: true, takesValue: true, metavar: 'KEY' },
  { key: 'iv', long: 'iv', required: true, takesValue: true, metavar: 'IV' },
  { key: 'data1', long: 'data1', required: true, takesValue: true, metavar: 'DATA1' },
  { key: 'data2', long: 'data2', required: true, takesValue: true, metavar: 'DATA2' },
];

const NEGATIVE_NUMBER_PATTERN =
  /^-\d+(\.\d*)?([eE][+-]?\d+)?$/u;
const NEGATIVE_FRACTION_PATTERN =
  /^-\.\d+([eE][+-]?\d+)?$/u;

function looksLikeOption(token) {
  return token.length > 1 && token.startsWith('-');
}

function isNegativeNumberLike(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token) || NEGATIVE_FRACTION_PATTERN.test(token);
}

function resolveLongOption(name) {
  const matches = OPTION_SPECS.filter((spec) => spec.long.startsWith(name));

  if (matches.length === 0) {
    return { spec: null, ambiguous: null };
  }

  const exactMatch = matches.find((spec) => spec.long === name);
  if (exactMatch) {
    return { spec: exactMatch, ambiguous: null };
  }

  if (matches.length > 1) {
    return { spec: null, ambiguous: matches };
  }

  return { spec: matches[0], ambiguous: null };
}

function scanForAmbiguousOptions(argv) {
  for (const token of argv) {
    if (!token.startsWith('--') || token === '--') {
      continue;
    }

    const equalsIndex = token.indexOf('=');
    const optionName = token.slice(2, equalsIndex === -1 ? undefined : equalsIndex);
    const resolution = resolveLongOption(optionName);

    if (resolution.ambiguous !== null) {
      return {
        token,
        matches: resolution.ambiguous.map((spec) => `--${spec.long}`),
      };
    }
  }

  return null;
}

export function getProgramName(argvEntry) {
  if (!argvEntry) {
    return 'test7.mjs';
  }

  const normalizedPath = argvEntry.replace(/\\/gu, '/');
  const separatorIndex = normalizedPath.lastIndexOf('/');
  return separatorIndex === -1 ? normalizedPath : normalizedPath.slice(separatorIndex + 1);
}

export function createUsageText(programName) {
  return `usage: ${programName} [-h] --key KEY --iv IV --data1 DATA1 --data2 DATA2`;
}

export function createHelpText(programName) {
  return `${createUsageText(programName)}

options:
  -h, --help     show this help message and exit
  --key KEY
  --iv IV
  --data1 DATA1
  --data2 DATA2
`;
}

export function writeHelp(programName, stdout = process.stdout) {
  stdout.write(createHelpText(programName));
}

export function writeCliError(programName, message, stderr = process.stderr) {
  stderr.write(`${createUsageText(programName)}
${programName}: error: ${message}
`);
}

export function parseArgs(argv) {
  const ambiguousOption = scanForAmbiguousOptions(argv);
  if (ambiguousOption !== null) {
    throw new CliArgumentError(
      `ambiguous option: ${ambiguousOption.token} could match ${ambiguousOption.matches.join(', ')}`,
    );
  }

  const parsedValues = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === '-h') {
      return { help: true, values: parsedValues };
    }

    if (token.startsWith('-h') && !token.startsWith('--')) {
      if (token.startsWith('-h=')) {
        throw new CliArgumentError(`argument -h/--help: ignored explicit argument '${token.slice(3)}'`);
      }
      return { help: true, values: parsedValues };
    }

    if (token.startsWith('--') && token !== '--') {
      const equalsIndex = token.indexOf('=');
      const optionName = token.slice(2, equalsIndex === -1 ? undefined : equalsIndex);
      const resolution = resolveLongOption(optionName);

      if (resolution.spec === null) {
        extras.push(token);
        continue;
      }

      if (!resolution.spec.takesValue) {
        if (equalsIndex !== -1) {
          throw new CliArgumentError(
            `argument -h/--help: ignored explicit argument '${token.slice(equalsIndex + 1)}'`,
          );
        }
        return { help: true, values: parsedValues };
      }

      if (equalsIndex !== -1) {
        parsedValues[resolution.spec.key] = token.slice(equalsIndex + 1);
        continue;
      }

      const nextToken = argv[index + 1];
      if (
        nextToken === undefined ||
        (looksLikeOption(nextToken) && !isNegativeNumberLike(nextToken))
      ) {
        throw new CliArgumentError(`argument --${resolution.spec.long}: expected one argument`);
      }

      parsedValues[resolution.spec.key] = nextToken;
      index += 1;
      continue;
    }

    if (looksLikeOption(token) && !isNegativeNumberLike(token)) {
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missingRequired = OPTION_SPECS
    .filter((spec) => spec.required && parsedValues[spec.key] === undefined)
    .map((spec) => `--${spec.long}`);

  if (missingRequired.length > 0) {
    throw new CliArgumentError(`the following arguments are required: ${missingRequired.join(', ')}`);
  }

  if (extras.length > 0) {
    throw new CliArgumentError(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return { help: false, values: parsedValues };
}

function toHex(byte) {
