export function formatPythonBytes(bytes) {
  let rendered = "b'";

  for (const byte of bytes) {
    if (byte === 0x27) {
      rendered += "\\'";
    } else if (byte === 0x5c) {
      rendered += '\\\\';
    } else if (byte === 0x09) {
      rendered += '\\t';
    } else if (byte === 0x0a) {
      rendered += '\\n';
    } else if (byte === 0x0d) {
      rendered += '\\r';
    } else if (byte >= 0x20 && byte <= 0x7e) {
      rendered += String.fromCharCode(byte);
    } else {
      rendered += `\\x${toHex(byte)}`;
    }
  }

  rendered += "'";
  return rendered;
}

import { AesEncryptor } from './aes_core.mjs';
import { ValueError } from './errors.mjs';

function xorBlocks(left, right) {
  const result = new Uint8Array(16);

  for (let index = 0; index < result.length; index += 1) {
    result[index] = left[index] ^ right[index];
  }

  return result;
}

export class AesModeOfOperationCBC {
  constructor(keyBytes, ivBytes) {
    if (ivBytes.length !== 16) {
      throw new ValueError('initialization vector must be 16 bytes');
    }

    this.blockCipher = new AesEncryptor(keyBytes);
    this.lastCipherBlock = Uint8Array.from(ivBytes);
  }

  encrypt(plaintextBlock) {
    if (plaintextBlock.length !== 16) {
      throw new ValueError('plaintext block must be 16 bytes');
    }

    const chainedBlock = xorBlocks(plaintextBlock, this.lastCipherBlock);
    const ciphertext = this.blockCipher.encryptBlock(chainedBlock);
    this.lastCipherBlock = Uint8Array.from(ciphertext);
    return ciphertext;
  }
}

