const OPTION_ORDER = [
  { longName: '--key', destination: 'key', metavar: 'KEY' },
  { longName: '--iv', destination: 'iv', metavar: 'IV' },
  { longName: '--data1', destination: 'data1', metavar: 'DATA1' },
  { longName: '--data2', destination: 'data2', metavar: 'DATA2' },
];

const LONG_OPTION_NAMES = ['--help', ...OPTION_ORDER.map((option) => option.longName)];

function getProgramName(programPath) {
  if (!programPath) {
    return 'test7.mjs';
  }

  const normalized = programPath.replaceAll('\\', '/');
  const lastSlash = normalized.lastIndexOf('/');
  return lastSlash === -1 ? normalized : normalized.slice(lastSlash + 1);
}

function formatUsage(programName) {
  return `usage: ${programName} [-h] --key KEY --iv IV --data1 DATA1 --data2 DATA2`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}

options:
  -h, --help     show this help message and exit
  --key KEY
  --iv IV
  --data1 DATA1
  --data2 DATA2
`;
}

function formatParserError(programName, message) {
  return `${formatUsage(programName)}
${programName}: error: ${message}
`;
}

function isOptionLike(token) {
  return token.length > 1 && token.startsWith('-');
}

function resolveLongOption(optionToken) {
  const matches = LONG_OPTION_NAMES.filter((candidate) => candidate.startsWith(optionToken));

  if (matches.length === 0) {
    return { type: 'unknown' };
  }

  if (matches.length > 1) {
    return { type: 'ambiguous', matches };
  }

  return { type: 'known', name: matches[0] };
}

function pushUnknownArgument(unknownArguments, argv, index) {
  unknownArguments.push(argv[index]);

  if (index + 1 < argv.length && !isOptionLike(argv[index + 1])) {
    unknownArguments.push(argv[index + 1]);
    return index + 1;
  }

  return index;
}

export function parseCommandLine(argv, programPath) {
  const programName = getProgramName(programPath);
  const values = Object.create(null);
  const unknownArguments = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      unknownArguments.push(...argv.slice(index + 1));
      break;
    }

    if (token === '-h' || token === '-help' || (token.startsWith('-h') && !token.startsWith('--'))) {
      if (token.startsWith('-h=')) {
        return {
          kind: 'error',
          status: 2,
          text: formatParserError(
            programName,
            `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
          ),
        };
      }

      return { kind: 'help', status: 0, text: formatHelp(programName) };
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const explicitValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const resolution = resolveLongOption(optionToken);

      if (resolution.type === 'ambiguous') {
        return {
          kind: 'error',
          status: 2,
          text: formatParserError(
            programName,
            `ambiguous option: ${optionToken} could match ${resolution.matches.join(', ')}`,
          ),
        };
      }

      if (resolution.type === 'unknown') {
        index = pushUnknownArgument(unknownArguments, argv, index);
        continue;
      }

      if (resolution.name === '--help') {
        if (explicitValue !== null) {
          return {
            kind: 'error',
            status: 2,
            text: formatParserError(
              programName,
              `argument -h/--help: ignored explicit argument '${explicitValue}'`,
            ),
          };
        }

        return { kind: 'help', status: 0, text: formatHelp(programName) };
      }

      const option = OPTION_ORDER.find((candidate) => candidate.longName === resolution.name);
      let value = explicitValue;

      if (value === null) {
        const nextToken = argv[index + 1];
        if (nextToken === undefined || isOptionLike(nextToken)) {
          return {
            kind: 'error',
            status: 2,
            text: formatParserError(programName, `argument ${option.longName}: expected one argument`),
          };
        }

        value = nextToken;
        index += 1;
      }

      values[option.destination] = value;
      continue;
    }

    if (token.startsWith('-')) {
      index = pushUnknownArgument(unknownArguments, argv, index);
      continue;
    }

    unknownArguments.push(token);
  }

  const missing = OPTION_ORDER
    .filter((option) => values[option.destination] === undefined)
    .map((option) => option.longName);

  if (missing.length > 0) {
    return {
      kind: 'error',
      status: 2,
      text: formatParserError(
        programName,
        `the following arguments are required: ${missing.join(', ')}`,
      ),
    };
  }

  if (unknownArguments.length > 0) {
    return {
      kind: 'error',
      status: 2,
      text: formatParserError(
        programName,
        `unrecognized arguments: ${unknownArguments.join(' ')}`,
      ),
    };
  }

  return { kind: 'ok', status: 0, values };
}
